class TokenAuth:
    """JWT based helper class. Currently a wrapper over flask JWT.
    Implements features like:

    * Token generation
    * Token refresh
    """

    def __init__(self, secret_key=None, access_expiry=None,
                 refresh_expiry=None):
        pass

    def create_access_token(self, identity):
        return create_access_token(identity=identity)

    def create_refresh_token(self):
        pass

    def create_token(self, identity):
        """return both refresh and access token"""
        token = dict(access_token=create_access_token(identity=identity),
                     refresh_token=create_refresh_token(identity=identity))
        return token

    def refresh(self, refresh_token):
        return create_access_token()

    def blacklist(self, access_token, refresh_token, time_period):
        pass

unit.function:
def link_stats(short_code):
    """Get short link stats"""
    manager = LinkManager()
    short_code = short_code.strip('+')
    link = manager.get_by_code(short_code=short_code)
    return link if link is None else formatted_link_stats(link)

def formatted_link_stats(link): """Pass link and clickmeta model objects ans returns a formatted dict.
:param link: :param clickmeta: :return: """ manager = ClickMetaManager() click_meta = manager.click_stats(link.id) link_info = dict( long_url=link.long_url, short_code=link.short_code, created_at=link.created_at ) click_info = { 'total_hits': click_meta.get('hits', 0), 'country_stats': click_meta.get('country_hits', {}), 'referrer': click_meta.get('referrer_hits', {}), 'time_series_base': click_meta.get('time_base'), 'time_stats': click_meta.get('timestamp_hits', {}), }
# Hide original/long_url in case of protected links if link.is_protected is True: link_info['long_url'] = '' return {**link_info, **click_info}

def save_clickmeta(request, link):
    """Save public access info of short link.

    :param request:
    :param link:
    :return: ClickMeta
    """
    from pygmy.core.request_parser import parse_request, parse_header
    pygmy_header_key = config.pygmy_internal['pygmy_header_key']
    if request.headers.get('Pygmy-Header-Key') == pygmy_header_key:
        data = parse_header(request)
    else:
        data = parse_request(request)
    return ClickMetaManager().add(link_id=link.id, **data)

