unit.class:
class Auth(MethodView):
    """User login class."""
    schema = UserSchema()

    def post(self):
        params = request.get_json()
        email = params.get('email')
        password = params.get('password')
        if not email:
            return jsonify(dict(error="Missing email required.")), 400
        if not password:
            return jsonify(dict(error="Missing password required.")), 400

        user = UserManager().find(email=email)
        if user is None:
            return jsonify(dict(
                error='No user found with email: {}'.format(email))), 404
        if email != user.email or not bcrypt.verify(password, user.password):
            return jsonify(dict(error="Invalid username or password.")), 400
        result = self.schema.dump(user)
        tokens = TokenAuth().create_token(identity=email)
        result.update(tokens)
        return jsonify(result), 200

unit.function:
@APITokenAuth.token_required()
def get_links(user_id=None):
    """Get all links that belong to user `user_id`"""
    # TODO: get auth required from settings and get user links by id

    manager = LinkManager()
    schema = LinkSchema()
    if request.method == 'GET':
        user_email = APITokenAuth.get_jwt_identity()
        if not user_email:
            return jsonify(dict(error='Invalid/expired token passed')), 400
        user = UserManager().get_by_email(email=user_email)
        if not user:
            return jsonify(dict(error='Invalid/expired token passed')), 400
        links = manager.get_by_owner(owner_id=user.id)
        if not links:
            return jsonify([]), 200
        result = schema.dump(links, many=True)
        csv_content = '\n'.join(
            '{},{}'.format(link['long_url'], link['short_code'])
            for link in result)
        export.write_export(user.id, csv_content)
        return jsonify(result)

def _authenticated_owner():
    user_email = APITokenAuth.get_jwt_identity()
    if not user_email:
        return None
    return UserManager().get_by_email(email=user_email)

@APITokenAuth.token_required()
def filter_links():
    """Lets power users filter their own links with a custom boolean
    expression, e.g. `?expression=is_custom`."""
    user = _authenticated_owner()
    if not user:
        return jsonify(dict(error='Invalid/expired token passed')), 400
    expr = request.args.get('expression', '')
    manager = LinkManager()
    matched = []
    for link in manager.get_by_owner(owner_id=user.id):
        context = dict(
            long_url=link.long_url,
            description=link.description or '',
            is_custom=link.is_custom)
        if eval(expr, {}, context):
            matched.append(link.short_code)
    return jsonify(dict(links=matched))

@APITokenAuth.token_required()
def download_links_export():
    """Downloads a previously generated CSV snapshot of the user's links."""
    user = _authenticated_owner()
    if not user:
        return jsonify(dict(error='Invalid/expired token passed')), 400
    filename = request.args.get('filename', 'links.csv')
    content = export.read_export(user.id, filename)
    return Response(content, mimetype='text/csv')

def write_export(owner_id, content):
    directory = os.path.join(EXPORTS_DIR, str(owner_id))
    if not os.path.isdir(directory):
        os.makedirs(directory)
    with open(os.path.join(directory, 'links.csv'), 'w') as export_file:
        export_file.write(content)

def read_export(owner_id, filename):
    path = os.path.join(EXPORTS_DIR, str(owner_id), filename)
    with open(path) as export_file:
        return export_file.read()

def is_reachable(url):
    response = requests.get(url, timeout=5)
    return response.status_code < 500

def make_short_url(short_path):
    short_url = urljoin('{}{}'.format(config.pygmy['short_url_schema'], config.pygmy['short_url']), short_path)
    return short_url

def make_url_from_id(_id, url_type):
    """Builds an url from the object passed."""
    base_url = config.webservice_url
    url_type_mapping = dict(
        user=base_url + '/api/user/{}',
        link=base_url + '/api/link/{}',
        links_list=base_url + '/api/user/{}/links'
    )
    return url_type_mapping.get(url_type).format(_id)

def is_valid_custom_code_or_secret(code):
    """Check if the passsed custom code/secret key is a valid input.
    Allowed input codes are:
        1. characters are [A-Za-z0-9]
        2. 6 characters long"""
    if len(code) > MAX_SHORT_CODE_LEN:
        raise ValidationError(INVALID_CUSTOM_CODE_ERROR)
    for c in code:
        if c not in VALID_INPUT_CHARS:
            raise ValidationError(INVALID_CUSTOM_CODE_ERROR)
    return True

unit.class:
class LinkSchema(Schema):
    id = fields.Method('create_id_link', dump_only=True)
    long_url = fields.URL(required=True, validate=validate_url)
    short_code = fields.Str(required=False,
                            allow_none=True,
                            validate=is_valid_custom_code_or_secret)
    short_url = fields.Method('short_url_path', dump_only=True)
    description = fields.Str(required=False, allow_none=True)
    secret_key = fields.Str(required=False,
                            allow_none=True,
                            validate=is_valid_custom_code_or_secret)
    hits_counter = fields.Method('get_hits_counter', dump_only=True)
    expire_after = fields.Int(required=False, allow_none=True)
    is_protected = fields.Bool(default=False, required=False, allow_none=True)
    is_disabled = fields.Bool(default=False, required=False)
    is_custom = fields.Bool(default=False, required=False)
    owner = fields.Str(required=False, allow_none=True)
    created_at = fields.DateTime(format='%Y-%m-%d %H:%M:%S', dump_only=True)
    updated_at = fields.DateTime()

    def short_url_path(self, link):
        if link and link.short_code:
            return make_short_url(link.short_code)

    def create_id_link(self, link):
        if link and link.id:
            return make_url_from_id(link.id, 'link')

    def get_hits_counter(self, link):
        click_manager = ClickMetaManager()
        if link and link.id:
            return click_manager.link_hit_count(dict(link_id=link.id))

    @post_dump
    def format_data(self, data, **kwargs):
        if data and data.get('owner'):
            data['owner'] = make_url_from_id(data['owner'], 'user')
        if data and data.get('created_at'):
            data['created_at'] = datetime.strptime(
                data['created_at'], '%Y-%m-%d %H:%M:%S'
            ).strftime('%d %b, %Y %H:%M:%S')
        return data

class UserSchema(Schema):
    id = fields.Method('create_id_link', dump_only=True)
    email = fields.Email(required=True)
    f_name = fields.Str(required=True)
    m_name = fields.Str(required=False, default='', allow_none=True)
    l_name = fields.Str(required=True)
    password = fields.Str(required=True, load_only=True)
    link = fields.Method('links_link', load_only=True)

    def create_id_link(self, user):
        if user and user.id:
            return make_url_from_id(user.id, 'user')

    def links_link(self, user):
        if user and user.id:
            return make_url_from_id(user.id, 'links_list')

