unit.function:
def catch_connection_error(func):
    @wraps(func)
    def _wrapped(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except requests.ConnectionError:
            # TODO: Error from the error class not hard coded.
            raise RestAPIConnectionError("Connection to Pygmy API Failed.")
    return _wrapped

unit.class:
class Client:
    """This is an Abstract Base Class"""

    def __init__(
            self, base_url, basic_auth=False, username=None, password=None,
            request_data_type='json', return_for_status=[]):
        """Pass username and password as None when basic auth is disabled"""
        self.rest_url = base_url
        self.basic_auth = None
        self.request_data_type = request_data_type
        if return_for_status and not isinstance(return_for_status, list):
            return_for_status = [return_for_status]
        self.return_for_status = return_for_status

        if basic_auth is True:
            if password is None or username is None:
                raise RestClientException(
                    '`username` and `password` are required when `basic_auth` is True'
                )
            self.basic_auth = requests.auth.HTTPBasicAuth(username, password)

    @property
    def header(self):
        raise NotImplementedError

    @staticmethod
    def makeurl(base_url, path):
        return urljoin(base_url, path)

    def call(self, path, data=None, method=None,
             return_for_status=[], headers=None):
        """
        The wrapper over `requests` library.
        :param path: url_path
        :param data: Post data, None in case of GET
        :type data: json/dict
        :param method: None or GET/POST
        :type method: str
        :param return_for_status: Status codes which should be raised instead of
            being handled here, so that calling method can handle it in it's
            own custom way.
        :type return_for_status: str/list
        :param headers: Add parameters to header
        :type headers: dict
        :return:
        """
        header_params = self.header
        header_params.update({'User-Agent': 'Pygmy API REST client'})
        if headers:
            header_params.update(headers)

        request_param = dict(
            url=self.makeurl(self.rest_url, path), auth=self.basic_auth, headers=header_params
        )

        _call = requests.get
        if method is None:
            method = 'GET' if data is None else 'POST'
        if method.upper() == 'POST':
            _call = requests.post
            if self.request_data_type == 'json':
                request_param['json'] = data
            else:
                request_param['data'] = data
        # Make rest call and handle the response
        response = _call(**request_param)

        if return_for_status and not isinstance(return_for_status, list):
            return_for_status = [return_for_status]
        return_for_status = self.return_for_status + return_for_status
        if response.status_code in return_for_status:
            return response

        error_object = self.error_object_from_response(response)
        if error_object is not None:
            logger.debug('Reveived error response: %s', response.text)
            raise error_object
        return response

    @staticmethod
    def error_object_from_response(response):
        error_object = None
        if response.status_code == BAD_REQUEST:
            error_object = InvalidInput(response.json())
        elif response.status_code == FORBIDDEN:
            error_object = UnAuthorized(response.json())
        elif response.status_code == RESOURCE_EXPIRED:
            error_object = LinkExpired(response.json())
        elif response.status_code // 100 != 2:
            error_object = ObjectNotFound(response.json())
        return error_object

unit.function:
def API_ERROR(error_message):
    """Method to create error dict. Used for redering error in templates"""
    try:
        if not isinstance(error_message, dict):
            try:
                error_message = json.loads(error_message).get('error')
            except json.decoder.JSONDecodeError:
                pass
        elif isinstance(error_message, dict):
            error_message = error_message.get('error')
    except Exception:
        import traceback
        traceback.print_exc()
        error_message = INTERNAL_SERVER_ERROR_API
    return dict(error=error_message if isinstance(error_message,list) else [error_message])

unit.class:
class PygmyApiClient(Client): """Pygmy REST API wrapper class"""
def __init__(self, rest_url, username, password, hostname, request=None): """ Arguments: rest_url {[type]} -- Pygmy API url username {[type]} -- api username password {[type]} -- api password hostname {[type]} -- the pygmy website/ui hostname. Used to create the short url """
self.name = username self.password = password self.rest_url = rest_url scheme = 'http://' if not urlparse(hostname).scheme else '' self.HOSTNAME = '{}{}'.format(scheme, hostname) self.request = request self.cookies = None if request is None else request.COOKIES super().__init__(rest_url, basic_auth=True, username=username, password=password)
def __repr__(self): return '<PygmyApiClient ({0.name}:{0.password}) {0.rest_url}>'.format( self)
@property def header(self): _header = dict() if self.request is None: return _header if self.cookies and self.cookies.get(AUTH_COOKIE_NAME): _header = dict(JWT_Authorization='Bearer {}'.format( self.cookies.get(AUTH_COOKIE_NAME))) remote_addr = self.request.META.get('REMOTE_ADDR') _header['Pygmy-App-User-Ip'] = self.request.META.get( 'HTTP_X_REAL_IP', remote_addr) _header['Pygmy-Http-Rreferrer'] = self.request.META.get('HTTP_REFERER') _header['Pygmy-Http-User-Agent'] = self.request.META.get( 'HTTP_USER_AGENT') _header['Pygmy-Header-Key'] = 'KJ*57*6)(*&^dh' return _header
@property def refresh_header(self): if self.cookies and self.cookies.get(REFRESH_COOKIE_NAME): return dict(JWT_Authorization='Bearer {}'.format( self.cookies.get(REFRESH_COOKIE_NAME)))
@catch_connection_error def refresh_access_token(self): access_token = None url_path = self.rest_url + '/token/refresh' resp = requests.post(url_path, headers=self.refresh_header) if resp.status_code == 401: self.request.COOKIES[REFRESH_COOKIE_NAME] = None self.request.COOKIES[AUTH_COOKIE_NAME] = None if resp.status_code == 200: access_token = resp.json()[AUTH_COOKIE_NAME] self.cookies[AUTH_COOKIE_NAME] = access_token self.request.COOKIES[AUTH_COOKIE_NAME] = access_token return {AUTH_COOKIE_NAME: access_token}
@catch_connection_error def ping(self): r = requests.get(self.rest_url, headers=self.header) if r.status_code // 100 == 2: return 'PONG'
@catch_connection_error def shorten(self, long_url, custom_code=None, description=None, owner=None, secret=None, expire_after=None): """Create the post payload for create short URL REST API. :param long_url: :param custom_code: :param description: :param owner: :param secret: :param expire_after: :return: """ url_path = '/api/shorten' payload = dict(long_url=long_url, short_code=custom_code, is_custom=custom_code is not None and custom_code != '', description=description, is_protected=secret is not None and secret != '', expire_after=expire_after, secret_key=secret, owner=owner) r = self.call(url_path, data=payload, return_for_status=401) resp = r.json() if int(r.status_code) == 401: if resp['sub_status'] == 101: self.refresh_access_token() if self.header is None: raise UnAuthorized('Please login again to continue') r = self.call(url_path, data=payload) resp = r.json() if resp.get('short_url'): resp['short_url'] = self.makeurl(self.HOSTNAME, resp['short_code']) return resp
@catch_connection_error def get_longurl_data(self, long_url): """ :param long_url: :return: """ url_path = '/api/shorten?url=' + long_url r = requests.get(self.rest_url + url_path, headers=self.header) if r.status_code // 100 != 2: raise ObjectNotFound(r.json()) return r.json()
@catch_connection_error def unshorten(self, short_url_code, secret=None): """ :param short_url_code: :param secret: :return: """ short_code = urlparse(short_url_code).path.strip('/') url_path = '/api/unshorten?url=' + self.rest_url + '/' + short_code r = self.call(url_path, headers=dict(secret_key=secret)) resp = r.json() if resp.get('short_code'): resp['short_url'] = self.makeurl(self.HOSTNAME, resp['short_code']) return resp
@catch_connection_error def login(self, email, password): """User login""" url_path = '/api/login' payload = dict(email=email, password=password) r = self.call(url_path, data=payload) resp = r.json() if resp.get('short_url'): resp['short_url'] = self.makeurl(self.HOSTNAME, resp['short_code']) return resp
@catch_connection_error def signup(self, data): """Signup :param data: :return: dict """ _ = data.pop('confirm_password') url_path = '/api/user' r = self.call(url_path, data=data) resp = r.json() if resp.get('short_url'): resp['short_url'] = self.makeurl(self.HOSTNAME, resp['short_code']) return resp
@catch_connection_error def list_links(self, access_token): """List of all user links. :param access_token: :return: dict """ user_path = '/api/user/links' headers = self.header headers.update( dict(JWT_Authorization='Bearer {}'.format(access_token))) r = requests.get(self.rest_url + user_path, headers=headers) resp_obj = r.json() if int(r.status_code) == 401: if resp_obj['sub_status'] == 101: self.refresh_access_token() if self.header is None: raise UnAuthorized('Please login again to continue') r = requests.get(self.rest_url + user_path, headers=self.header) resp_obj = r.json() if r.status_code // 100 != 2: if r.status_code == 401: return UnAuthorized('Please login again to continue') raise ObjectNotFound(resp_obj) links = resp_obj for link in links: if link.get('short_code'): link['short_url'] = self.makeurl( self.HOSTNAME, link['short_code']) return links
@catch_connection_error def is_available(self, short_code): """Pass a short url code and it tells weather that is available or not.
:param short_code: :return: bool """ try: resp = self.unshorten(short_code) available = not(resp is not None) except (UnAuthorized, LinkExpired): available = False except ObjectNotFound: available = True return available
@catch_connection_error def link_stats(self, short_code, secret_key=None): """Pass a short url code and it returns the stats of of the url.
:param short_code: :param secret_key: :return: dict """ # make sure + is added in the code short_code = urlparse(short_code).path.strip('/') short_code = short_code.strip('+') + '+' headers = self.header headers.update(dict(secret_key=secret_key)) r = self.call(short_code, return_for_status=401) resp = r.json() if int(r.status_code) == 401: if resp['sub_status'] == 101: self.refresh_access_token() if self.header is None: raise UnAuthorized('Please login again to continue') r = self.call(short_code) resp = r.json() if resp.get('short_code'): resp['short_url'] = self.makeurl(self.HOSTNAME, resp['short_code']) return resp

